from itertools import product
from random import Random

from solution import search


def contract_oracle(values):
    qualifying = [
        value
        for value in set(values)
        if values.count(value) >= value
    ]
    return max(qualifying) if qualifying else -1


cases = []
for length in range(1, 7):
    cases.extend(list(values) for values in product(range(1, 6), repeat=length))

rng = Random(20260729)
for _ in range(500):
    length = rng.randint(1, 30)
    cases.append([rng.randint(1, 30) for _ in range(length)])

mismatches = []
for values in cases:
    expected = contract_oracle(values)
    actual = search(values)
    if actual != expected:
        mismatches.append((values, expected, actual))

print(f"cases={len(cases)} mismatches={len(mismatches)}")
if mismatches:
    for mismatch in mismatches[:10]:
        print(mismatch)
    raise SystemExit(1)

/workspace/check_program_identity.py.content:
from pathlib import Path


def compact_k(text):
    output = []
    quoted = False
    escaped = False
    for char in text:
        if quoted:
            output.append(char)
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == '"':
                quoted = False
        elif char == '"':
            quoted = True
            output.append(char)
        elif not char.isspace():
            output.append(char)
    return "".join(output)


translated = Path("solution.mpy").read_text(encoding="utf-8").strip()
specification = Path("spec.k").read_text(encoding="utf-8")
marker = "#loadAll("
start = specification.index(marker) + len(marker)

depth = 1
quoted = False
escaped = False
end = None
for offset, char in enumerate(specification[start:], start=start):
    if quoted:
        if escaped:
            escaped = False
        elif char == "\\":
            escaped = True
        elif char == '"':
            quoted = False
        continue
    if char == '"':
        quoted = True
    elif char == "(":
        depth += 1
    elif char == ")":
        depth -= 1
        if depth == 0:
            end = offset
            break

if end is None:
    raise SystemExit("program identity: unmatched #loadAll parenthesis")

embedded = specification[start:end]
if compact_k(translated) != compact_k(embedded):
    raise SystemExit("program identity: solution.mpy differs from spec.k")

print("program identity: PASS")

